export async function listTools() {
  return [
    {
      name: 'search_records',
      description: 'Search records by case-insensitive name.',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Substring to match against record names (case-insensitive).' },
          limit: { type: 'integer', minimum: 1, maximum: 4, default: 2, description: 'Maximum number of matching records to return (1..4, default 2).' }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'search_records') {
    throw validationError(`Unknown tool: ${name}`);
  }
  const { query, limit = 2, ...rest } = args;
  if (Object.keys(rest).length > 0) {
    throw validationError(`Unexpected arguments: ${Object.keys(rest).join(', ')}`);
  }
  if (typeof query !== 'string') {
    throw validationError('query must be a string');
  }
  if (!Number.isInteger(limit)) {
    throw validationError('limit must be an integer');
  }
  if (limit < 1 || limit > 4) {
    throw validationError('limit must be between 1 and 4');
  }
  const q = query.toLowerCase();
  const matches = records.filter(r => r.name.toLowerCase().includes(q)).slice(0, limit);
  return {
    content: [{ type: 'text', text: JSON.stringify({ records: matches }) }]
  };
}
